// A tiny Flutter bridge for code generated by cljd2dart.
//
// cljd2dart emits plain Dart calls without named arguments, so Flutter
// constructors (which use lots of named parameters) are wrapped here as
// positional functions. The generated ClojureDart code only talks to this
// file, which keeps the app source free of Dart class definitions.
//
// ignore_for_file: avoid_dynamic_calls, avoid_print

import 'package:flutter/material.dart';

/// Starts the Flutter app.
dynamic launch(dynamic app) => runApp(app as Widget);

/// Builds the root [MaterialApp].
dynamic materialApp(String title, dynamic home) => MaterialApp(
      title: title,
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.indigo,
        useMaterial3: true,
      ),
      home: home as Widget,
    );

/// Wraps a builder in a [StatefulBuilder], providing a `setState` callback.
dynamic stateful(dynamic builder) => StatefulBuilder(
      builder: (context, setState) => builder((dynamic callback) {
        setState(() {
          callback();
        });
      }) as Widget,
    );

dynamic scaffold(dynamic appBar, dynamic body) => Scaffold(
      appBar: appBar as PreferredSizeWidget?,
      body: body as Widget,
    );

dynamic appBar(String title) => AppBar(title: Text(title));

dynamic center(dynamic child) => Center(child: child as Widget);

dynamic padding(double all, dynamic child) => Padding(
      padding: EdgeInsets.all(all),
      child: child as Widget,
    );

dynamic column(dynamic children) => Column(
      mainAxisSize: MainAxisSize.min,
      children: List<Widget>.from((children as List).map((w) => w as Widget)),
    );

dynamic row(dynamic children) => Row(
      mainAxisSize: MainAxisSize.min,
      children: List<Widget>.from((children as List).map((w) => w as Widget)),
    );

dynamic text(String data, [double size = 16]) => Text(
      data,
      style: TextStyle(fontSize: size),
    );

dynamic elevatedButton(String label, dynamic onPressed) => ElevatedButton(
      onPressed: () => onPressed(),
      child: Text(label),
    );

dynamic textButton(String label, dynamic onPressed) => TextButton(
      onPressed: () => onPressed(),
      child: Text(label),
    );
